import pandas as pd

def clean(df):
    df = df.copy()

    for col in ['species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()

    if 'species' in df.columns:
        df['species'] = df['species'].str.title()

    if 'island' in df.columns:
        df['island'] = df['island'].str.title().replace({
            'Bisco': 'Biscoe',
            'Dram': 'Dream'
        })

    if 'sex' in df.columns:
        df['sex'] = df['sex'].str.lower()

    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    if 'flipper_length_mm' in df.columns:
        neg = df['flipper_length_mm'] < 0
        df.loc[neg, 'flipper_length_mm'] = df.loc[neg, 'flipper_length_mm'].abs()

    df = df.drop_duplicates()

    if 'penguin_id' in df.columns:
        df = df.drop_duplicates(subset=['penguin_id'], keep='first')

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['island'])

    if 'penguin_id' in d.columns:
        counts = d.groupby('island')['penguin_id'].nunique()
    else:
        counts = d.groupby('island').size()

    return {str(k): int(v) for k, v in counts.items()}
